fn is_ascii_digit(c: char) -> bool {
    // Check if character is in the range '0' to '9'
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // For each character in the string, check if it is an ASCII digit.
    // The empty string returns true because there are no non-digit characters.
    s.chars().all(|c| is_ascii_digit(c))
}